void FbTFT::LCD_UpdateScreen()
{
    // 获取屏幕截图
    QScreen *screen = QApplication::primaryScreen();
    if (!screen) return;

    auto pixmap = new QPixmap(screen->grabWindow(0, 100, 100, 220, 300));
    if(pixmap->isNull()) {
        delete pixmap;
        return;
    }

    auto image = new QImage(pixmap->toImage().convertToFormat(QImage::Format_RGB888));
    delete pixmap; // 不再需要pixmap，释放内存
    if(image->isNull()) {
        delete image;
        return;
    }

    // 确保图像是在RGB格式下
    if (image->format() != QImage::Format_RGB888) {
        auto tempImage = new QImage(image->convertToFormat(QImage::Format_RGB888));
        delete image; // 替换image前，释放原image的内存
        image = tempImage;
    }

    const int width = image->width();
    const int height = image->height();
    const uchar *data = image->bits();
    if(data == nullptr) {
        delete image;
        return;
    }
    int bytesPerLine = image->bytesPerLine();
    qDebug() << width << height << bytesPerLine;

    auto rgbData = new QByteArray(); // 用于存储RGB数据的数组

    LCD_SetWindows(100, 100, 320, 400);

    for (int y = 0; y < height; ++y) {
        const uchar *line = data + y * bytesPerLine;
        for (int x = 0; x < width; ++x) {
            // 对于Format_RGB888，可以直接按照RGB顺序读取三个字节
            uchar r = line[x*3];
            uchar g = line[x*3 + 1];
            uchar b = line[x*3 + 2];
            // 将RGB值添加到数组中
            rgbData->append(r);
            rgbData->append(g);
            rgbData->append(b);
        }
    }

    const int maxChunkSize = 3000; // 最大块大小
    for (int i = 0; i < rgbData->size(); i += maxChunkSize) {
        QByteArray chunk = rgbData->mid(i, maxChunkSize);
        #ifdef Q_OS_LINUX
        int result = write(devfd, chunk.constData(), chunk.size());
        if (result == -1) {
            // 错误处理
            break;
        }
        #endif
    }

    delete image; // 释放image内存
    delete rgbData; // 释放rgbData内存
}

/*****************************************************************************
 * @name       :void LCD_DrawPoint(u16 x,u16 y)
 * @date       :2018-08-09
 * @function   :Write a pixel data at a specified location
 * @parameters :x:the x coordinate of the pixel
                y:the y coordinate of the pixel
 * @retvalue   :None
******************************************************************************/
void FbTFT::LCD_DrawPoint(uint16_t x,uint16_t y)
{
    LCD_SetCursor(x,y);
    Lcd_WriteData_16Bit(0x0000);
}

void FbTFT::LCD_Address_Set(uint16_t x1,uint16_t y1,uint16_t x2,uint16_t y2)
{

        LCD_WR_REG(0x2a);
        LCD_WR_DATA(x1);
        LCD_WR_DATA(x2);
        LCD_WR_REG(0x2b);
        LCD_WR_DATA(y1);
        LCD_WR_DATA(y2);
        LCD_WR_REG(0x2c);
}
void FbTFT::LCD_Init(void)
{


    LCD_BLK_Clr();
    LCD_RESET();
    LCD_WR_REG(0XF7);
    LCD_WR_DATA(0xA9);
    LCD_WR_DATA(0x51);
    LCD_WR_DATA(0x2C);
    LCD_WR_DATA(0x82);
    LCD_WR_REG(0xC0);
    LCD_WR_DATA(0x11);
    LCD_WR_DATA(0x09);
    LCD_WR_REG(0xC1);
    LCD_WR_DATA(0x41);
    LCD_WR_REG(0XC5);
    LCD_WR_DATA(0x00);
    LCD_WR_DATA(0x0A);
    LCD_WR_DATA(0x80);
    LCD_WR_REG(0xB1);
    LCD_WR_DATA(0xB0);
    LCD_WR_DATA(0x11);
    LCD_WR_REG(0xB4);
    LCD_WR_DATA(0x02);
    LCD_WR_REG(0xB6);
    LCD_WR_DATA(0x02);
    LCD_WR_DATA(0x42);
    LCD_WR_REG(0xB7);
    LCD_WR_DATA(0xc6);
    LCD_WR_REG(0xBE);
    LCD_WR_DATA(0x00);
    LCD_WR_DATA(0x04);
    LCD_WR_REG(0xE9);
    LCD_WR_DATA(0x00);
    LCD_WR_REG(0x36);
    LCD_WR_DATA((1<<3)|(0<<7)|(1<<6)|(1<<5));
    LCD_WR_REG(0x3A);
    LCD_WR_DATA(0x66);
    LCD_WR_REG(0xE0);
    LCD_WR_DATA(0x00);
    LCD_WR_DATA(0x07);
    LCD_WR_DATA(0x10);
    LCD_WR_DATA(0x09);
    LCD_WR_DATA(0x17);
    LCD_WR_DATA(0x0B);
    LCD_WR_DATA(0x41);
    LCD_WR_DATA(0x89);
    LCD_WR_DATA(0x4B);
    LCD_WR_DATA(0x0A);
    LCD_WR_DATA(0x0C);
    LCD_WR_DATA(0x0E);
    LCD_WR_DATA(0x18);
    LCD_WR_DATA(0x1B);
    LCD_WR_DATA(0x0F);
    LCD_WR_REG(0XE1);
    LCD_WR_DATA(0x00);
    LCD_WR_DATA(0x17);
    LCD_WR_DATA(0x1A);
    LCD_WR_DATA(0x04);
    LCD_WR_DATA(0x0E);
    LCD_WR_DATA(0x06);
    LCD_WR_DATA(0x2F);
    LCD_WR_DATA(0x45);
    LCD_WR_DATA(0x43);
    LCD_WR_DATA(0x02);
    LCD_WR_DATA(0x0A);
    LCD_WR_DATA(0x09);
    LCD_WR_DATA(0x32);
    LCD_WR_DATA(0x36);
    LCD_WR_DATA(0x0F);
    LCD_WR_REG(0x11);
    delay_ms(120);
    LCD_WR_REG(0x29);

    LCD_direction(USE_HORIZONTAL);

    LCD_Clear(BLUE);
    LCD_BLK_Set();




}
FbTFT::FbTFT(QObject *parent) : QThread(parent)
{
    #ifdef Q_OS_LINUX

    gpio_export(GPIO_BLK);
    gpio_dir_out(GPIO_BLK);

    gpio_export(GPIO_RES);
    gpio_dir_out(GPIO_RES);


    gpio_export(GPIO_DC);
    gpio_dir_out(GPIO_DC);


//    gpio_export(GPIO_CLK);
//    gpio_dir_out(GPIO_CLK);


//    gpio_export(GPIO_MOSI);
//    gpio_dir_out(GPIO_MOSI);

//    gpio_export(GPIO_CS);
//    gpio_dir_out(GPIO_CS);

    devfd = open("/dev/spidevfb0.0", O_RDWR);
    if (devfd < 0) {
        perror("Failed to open SPI device");

    }


    // 配置SPI传输参数
    //    int mode = SPI_MODE_3;  // CPOL=1, CPHA=1
    //    ioctl(fd, SPI_IOC_WR_MODE, &mode);  // 设置SPI模式

    int mode = SPI_MODE_3;    // SPI工作模式



    int bits = 8;             // 每个字节的位数
    int speed = 10000000;      // 传输速度

    ioctl(devfd, SPI_IOC_WR_MODE, &mode);       // 设置SPI模式
    ioctl(devfd, SPI_IOC_WR_BITS_PER_WORD, &bits);   // 设置每个字节的位数
    ioctl(devfd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);    // 设置传输速度


    // 获取当前模式
    if (ioctl(devfd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("Failed to get SPI mode");

    }
    printf("the mode is %02x\n",mode);




    //SPI1_read_write_byte(0Xff);


     //LCD_RES_Set();
//    LCD_RES_Set();
//    LCD_BLK_Set();
    #endif
}
/*******************************************************************************
* Function Name  : SPI_FLASH_SendByte
* Description    : Sends a byte through the SPI interface and return the byte
*                  received from the SPI bus.
* Input          : byte : byte to send.
* Output         : None
* Return         : The value of the received byte.
*******************************************************************************/
uint8_t FbTFT::SPI1_read_write_byte(uint8_t byte)
{
    uint8_t i;


//    //delay_ms(200);
//    //printf("%02x,rx_buffer[0]\n",byte);
//    for(i=0;i<8;i++)
//    {
//        LCD_SCLK_Clr();
//        if(byte&0x80)
//        {
//           LCD_MOSI_Set();
//        }
//        else
//        {
//           LCD_MOSI_Clr();
//        }
//        LCD_SCLK_Set();
//        byte<<=1;
//    }
//    LCD_CS_Set();

    unsigned char tx_buffer[2]={0};
    unsigned char rx_buffer[2]={0};

    #ifdef Q_OS_LINUX
    struct spi_ioc_transfer transfer;

    memset(&transfer,0,sizeof(struct spi_ioc_transfer));
    tx_buffer[0] = byte;
    transfer.tx_buf = (unsigned long)tx_buffer;
    transfer.rx_buf  =(unsigned long) rx_buffer;
    transfer.len = 1;

    int ret = ioctl(devfd, SPI_IOC_MESSAGE(1), &transfer);


    if (ret < 1)
    {
        //perror("ioctl()");
        //fprintf(stderr,"ioctl returned %d\n",ret);
    }
    //printf("%02x,%d,rx_buffer[0]\n",rx_buffer[0],ret);
    #endif

   // printf("%02x,rx_buffer[0]\n",rx_buffer[0]);
    return rx_buffer[0];



}
void FbTFT::LCD_ShowPicture(uint16_t x,uint16_t y,uint16_t length,uint16_t width,const uint8_t* pic)
{
    uint16_t i,j;
    uint32_t k=0;
    LCD_Address_Set(x,y,x+length-1,y+width-1);
    for(i=0;i<length;i++)
    {
        for(j=0;j<width;j++)
        {
            LCD_WR_DATA8(pic[k*2]);
            LCD_WR_DATA8(pic[k*2+1]);
            k++;
        }
    }
//    LCD_Address_Set(x,y,x+length-1,y+width-1);

//    scl300_write_reg_multi_byte(pic,length*width*2+1);

}
void FbTFT::LCD_Fill(uint16_t xsta,uint16_t ysta,uint16_t xend,uint16_t yend,uint16_t color)
{
    uint16_t i,j;
    LCD_Address_Set(xsta,ysta,xend-1,yend-1);
    for(i=ysta;i<yend;i++)
    {
        for(j=xsta;j<xend;j++)
        {
            LCD_WR_DATA(color);
        }
    }
}
